 private final Zones z;private final EditSessions sessions=new EditSessions();private final Map<UUID,Long> rate=new HashMap<>();private Object revision=new Object();private Zones.Config seenConfig;private Tuning.Data seenTuning;
 private Object revision(){if(seenConfig!=z.config||seenTuning!=Tuning.current){seenConfig=z.config;seenTuning=Tuning.current;revision=new Object();}return revision;}
 MobsAdmin(Zones z){this.z=z;net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener((net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedOutEvent e)->{sessions.remove(e.getEntity().getUUID());rate.remove(e.getEntity().getUUID());});}
 void clear(){sessions.clear();rate.clear();}
 private void check(ServerPlayer p){if(!p.hasPermissions(2))throw new IllegalArgumentException("Necesitas permiso de administrador (nivel 2)");z.ready();long now=System.currentTimeMillis();if(now-rate.getOrDefault(p.getUUID(),0L)<100)throw new IllegalArgumentException("Espera un instante antes de otra operación");rate.put(p.getUUID(),now);}
 public void request(ServerPlayer p,String section,String id){try{check(p);send(p,snapshot(p,section,id,""));}catch(Exception e){p.sendSystemMessage(Component.literal(message(e)));}}
 private void send(ServerPlayer p,JsonObject data){MobsNetwork.send(p,new MobsNetwork.JsonView(data.toString()));}
 private static String message(Exception e){return e.getMessage()==null?"Operación rechazada":e.getMessage();}
 private static JsonObject option(String id,String name){var o=new JsonObject();o.addProperty("id",id);o.addProperty("name",name);return o;}
 private static JsonArray choices(Map<String,String> names,boolean none){var a=new JsonArray();if(none)a.add(option("","Ninguno"));names.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(e->a.add(option(e.getKey(),e.getValue())));return a;}
 private Map<String,String> mobNames(){var m=new LinkedHashMap<String,String>();z.config.mobs().forEach((id,s)->m.put(id,s.name()));return m;}
 private JsonArray lootChoices(){var m=new LinkedHashMap<String,String>();z.config.loot().keySet().forEach(id->m.put(id,id));return choices(m,true);}
 private static JsonObject base(String section,String id,String title,String notice){var d=new JsonObject();d.addProperty("section",section);d.addProperty("id",id);d.addProperty("title",title);d.addProperty("notice",notice);return d;}
 private static void row(JsonObject d,String section,String id,String name){var row=option(id,name);row.addProperty("section",section);d.getAsJsonArray("entries").add(row);}
 private void field(JsonObject d,String key,String label,String kind,Object value,JsonArray choices){var f=new JsonObject();f.addProperty("key",key);f.addProperty("label",label);f.addProperty("kind",kind);f.addProperty("group",AdminSections.field(d.get("section").getAsString(),key));if(choices!=null)f.add("choices",choices);d.getAsJsonArray("fields").add(f);d.getAsJsonObject("values").addProperty(key,String.valueOf(value));}
 private void field(JsonObject d,String key,String label,String kind,Object value){field(d,key,label,kind,value,null);}
 private static void action(JsonObject d,String id,String label,String confirm){var a=option(id,label);a.addProperty("label",label);a.addProperty("group",AdminSections.action(d.get("section").getAsString(),id));if(confirm!=null)a.addProperty("confirm",confirm);d.getAsJsonArray("actions").add(a);}
