   if(!Set.of("cursed_one_forest","cursed_one_ice","cursed_one_crystal","oni_brute").contains(id))throw new IllegalArgumentException("Ataque inexistente");var a=Tuning.attack(id);var d=form(p,section,id,"Ataque · "+id,"attacks",notice.isBlank()?"20 ticks = 1 segundo. Se aplica a este tipo de criatura.":notice);field(d,"enabled","Ataques activados","bool",a.enabled());field(d,"cooldown","Espera entre ataques (ticks)","number",a.cooldown());field(d,"multiplier","Multiplicador de daño (0–5)","number",a.multiplier());if(!id.equals("oni_brute"))field(d,"windup","Preparación (ticks)","number",a.windup());field(d,"radius","Alcance de impacto (bloques)","number",a.radius());if(!id.equals("oni_brute"))field(d,"leap","Impulso hacia delante (0–1.5)","number",a.leap());if(id.equals("oni_brute")){field(d,"roarCooldown","Espera del rugido (ticks)","number",a.roarCooldown());field(d,"roarSeconds","Duración de efectos del rugido (s)","number",a.roarSeconds());field(d,"roarRadius","Alcance del rugido (1–24)","number",a.roarRadius());}return d;
