  if(section.equals("settings")){var s=Tuning.current.settings();var d=form(p,section,id,"Ajustes de Zian Mobs","home",notice.isBlank()?"Desactivar zonas pausa las apariciones; cancela encuentros para retirar mobs.":notice);field(d,"zones","Activar sistema de zonas","bool",s.zones());field(d,"bossbars","Mostrar barras de jefes","bool",s.bossbars());field(d,"leash","Mantener mobs dentro de su zona","bool",s.leash());return d;}
  if(section.equals("review")){var d=form(p,section,id,"Revisar entregas","home",notice.isBlank()?"Elige un jugador conectado o escribe el UUID de otro jugador.":notice);var names=new LinkedHashMap<String,String>();for(var player:z.server.getPlayerList().getPlayers())names.put(player.getUUID().toString(),player.getScoreboardName());names.putIfAbsent(p.getUUID().toString(),p.getScoreboardName());field(d,"online","Jugador conectado","choice",p.getUUID(),choices(names,false));field(d,"owner","UUID de otro jugador (opcional)","text","");action(d,"inspect","Consultar entregas pendientes",null);return d;}
